710	/** A paste with no lines, or with a line that is not {@code name,amount,date,note} as the claim form
711	 * takes them. */
712	@ResponseStatus(HttpStatus.BAD_REQUEST)
713	public class PasteLineException extends RuntimeException {
714	}
715	package net.officefloor.hq.app.paste;
716	
717	import java.math.BigDecimal;
718	import java.time.LocalDate;
719	import java.time.format.DateTimeParseException;
720	import java.util.ArrayList;
721	import java.util.List;
722	import java.util.regex.Pattern;
723	import net.officefloor.hq.app.claim.Claim;
724	import net.officefloor.hq.app.claim.ClaimService;
725	import net.officefloor.hq.app.person.Person;
726	import net.officefloor.hq.app.person.PersonNotFoundException;
727	import net.officefloor.hq.app.person.PersonRepository;
728	import org.springframework.stereotype.Service;
729	import org.springframework.transaction.annotation.Transactional;
730	
731	/** Adds a DRAFT claim per pasted line of {@code name,amount,date,note}, in order, for the person on the
732	 * sheet with that name (compared as names are). The date may be blank (the sheet's today); the note may
733	 * hold commas, or be left out. Each line is held to the claim form's rules; it is one change: when any
734	 * line is refused no claim is added, and nothing is recorded. Blank lines are skipped. */
735	@Service
736	public class PasteService {
737	
738	    /** An amount as the claim form takes it. */
739	    private static final Pattern AMOUNT = Pattern.compile("\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*");
740	
741	    /** The longest note the claim form takes. */
742	    private static final int NOTE_MAX = 500;
743	
744	    private final PersonRepository people;
745	    private final ClaimService claimService;
746	
747	    public PasteService(PersonRepository people, ClaimService claimService) {
748	        this.people = people;
749	        this.claimService = claimService;
750	    }
751	
752	    /** The claims added, in the order of their lines. */
753	    @Transactional
754	    public List<Claim> paste(String sheetId, String user, String text) {
755	        List<Claim> added = new ArrayList<>();
756	        for (String line : text.split("\\r?\\n")) {
757	            if (line.isBlank()) continue;
758	            String[] fields = line.split(",", 4);
759	            if (fields.length < 2 || fields[0].isBlank() || !AMOUNT.matcher(fields[1]).matches()) {
760	                throw new PasteLineException();
761	            }
762	            Person person = people.findBySheetIdAndNameKey(sheetId, Person.keyOf(fields[0]))
763	                    .orElseThrow(PersonNotFoundException::new);
764	            String note = fields.length > 3 ? fields[3].trim() : "";
765	            if (note.length() > NOTE_MAX) throw new PasteLineException();
766	            BigDecimal amount = new BigDecimal(fields[1].trim()).setScale(2);
767	            added.add(claimService.add(sheetId, user, person.getId(), amount, dateOf(fields), note, null));
768	        }
769	        if (added.isEmpty()) throw new PasteLineException();
770	        return added;
771	    }
772	
773	    /** The line's date; null when it is blank or left out. */
774	    private static LocalDate dateOf(String[] fields) {
775	        if (fields.length < 3 || fields[2].isBlank()) return null;
776	        try {
777	            return LocalDate.parse(fields[2].trim());
778	        } catch (DateTimeParseException e) {
779	            throw new PasteLineException();
780	        }
781	    }
782	}
